let creationInput={audience:'有养老规划需求、担心资金流动性的人',platform:'抖音',reference:'准备长期养老资金之前，先问自己：这笔钱近期会不会用到？不要只盯着一个数字，也要看使用限制。'},messageDraft='',editingActivity=null,editingReview=null,planExtraction=null;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s+'T00:00:00+08:00'))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;
const nullableNumber=(value,label='数值')=>{if(value===null||value===undefined||String(value).trim()===''||/未确认|待确认/.test(String(value)))return null;const cleaned=String(value).replace(/[,，￥¥元\s]/g,'');if(cleaned===''||!/^\d+(?:\.\d+)?$/.test(cleaned))throw new Error(`${label}必须是大于等于 0 的有限数值，未知请留空。`);const n=Number(cleaned);if(!Number.isFinite(n)||n<0)throw new Error(`${label}必须是大于等于 0 的有限数值，未知请留空。`);return n;};
const numberValue=value=>nullableNumber(value)??0;
const moneyLabel=value=>{if(value===null||value===undefined||value===''||/未确认|待确认|不适用/.test(String(value)))return String(value||'未确认');const n=nullableNumber(value,'金额');return new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:0}).format(n);};
const formatRate=value=>Number.isFinite(value)?`${(Math.abs(value)<.00005?0:value*100).toFixed(2)}%`:'—';
function selectedOpportunity(c){const rows=c?.opportunities||[];return rows.find(item=>item.opportunity_id===(c.selectedOpportunityId||c.selected_opportunity_id))||rows[0]||null;}
function planConditionSnapshot(c){const opportunity=selectedOpportunity(c);return {customer_id:c?.customer_id||c?.id||null,person_id:opportunity?.person_id||c?.person_id||null,opportunity_id:opportunity?.opportunity_id||null,profile_version:Number(c?.profile_version||c?.profileVersion||1),opportunity_revision:Number(opportunity?.revision||c?.opportunity_revision||1),purpose:opportunity?.purpose??c?.purpose??null,age:opportunity?.age??c?.age??null,gender:opportunity?.gender??c?.gender??null,budget_amount:opportunity?.budget_amount??c?.budget_amount??null,budget_currency:opportunity?.budget_currency||c?.budget_currency||'CNY',plan:opportunity?.plan??c?.plan??null,paymentTerm:opportunity?.payment_term??c?.paymentTerm??null,premium:opportunity?.premium??c?.premium??null,receiveMode:opportunity?.receive_mode??c?.receiveMode??null,pensionAccount:opportunity?.pension_account??c?.pensionAccount??null};}
const samePlanSnapshot=(left,right)=>Boolean(left&&right&&JSON.stringify(left)===JSON.stringify(right));
const planIsCurrent=(book,c=typeof current==='function'?current():null)=>Boolean(book?.confirmed&&book.productVersion===state.product.version&&book.rows?.length&&samePlanSnapshot(book.conditionSnapshot,planConditionSnapshot(c)));
const planProfileFields=[['age','年龄'],['gender','性别'],['plan','保障计划'],['paymentTerm','交费期间'],['premium','年交／趸交保费'],['receiveMode','领取方式'],['pensionAccount','个人养老金资金账户']];
const missingPlanProfile=c=>planProfileFields.filter(([key])=>!c[key]||/未确认|待确认|待重新确认/.test(String(c[key]))).map(([,label])=>label);
function profileEditorHTML(c){const opportunity=typeof activeOpportunity==='function'?activeOpportunity(c):null,budget=opportunity?.budget_amount??c.budget_amount??'',connected=typeof v2Runtime!=='undefined'&&v2Runtime.status==='connected';const purpose=`<label class="field"><span>给谁／用途</span><input class="input" id="profile-purpose" value="${escapeHTML(opportunity?.purpose??c.purpose)}"></label>`,budgetField=`<label class="field"><span>预算金额（元）</span><input class="input" id="profile-budget" inputmode="decimal" value="${escapeHTML(budget)}" placeholder="例如：30000；未知留空"><small>只填有限非负数字，不填写“3万”或货币文字。</small></label>`,concern=`<label class="field"><span>主要顾虑</span><input class="input" id="profile-concern" value="${escapeHTML(opportunity?.concern??c.concern)}"></label>`;if(connected)return `<div class="equal-grid">${purpose}${budgetField}</div><div class="notice">人物、顾虑和计划书字段分别维护；这里的需求用途与预算会先保存到 v2 接口，成功后才更新页面。</div>`;const select=(key,options)=>`<select id="profile-${key}">${options.map(value=>`<option ${String(c[key])===value?'selected':''}>${value}</option>`).join('')}</select>`;return `<div class="equal-grid">${purpose}${budgetField}${concern}<label class="field"><span>被保险人年龄</span><input class="input" id="profile-age" value="${escapeHTML(c.age)}" placeholder="例如：38 岁"></label><label class="field"><span>性别</span>${select('gender',['待确认','男','女'])}</label><label class="field"><span>保障计划</span>${select('plan',['待确认','计划一','计划二'])}</label><label class="field"><span>交费期间</span>${select('paymentTerm',['待确认','趸交','3 年交','5 年交'])}</label><label class="field"><span>年交／趸交保费（元）</span><input class="input" id="profile-premium" inputmode="decimal" value="${escapeHTML(c.premium)}"></label><label class="field"><span>领取方式</span>${select('receiveMode',['待确认','年领','月领'])}</label><label class="field"><span>个人养老金资金账户</span>${select('pensionAccount',['待确认','否','是'])}</label></div>`;}
function parseCSVLine(line){const cells=[];let current='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'){if(quoted&&line[i+1]==='"'){current+='"';i++;}else quoted=!quoted;}else if((char===','||char==='，'||char==='\t')&&!quoted){cells.push(current.trim());current='';}else current+=char;}cells.push(current.trim());return cells;}
function normalizePlanRows(input){const aliases={year:['year','policyYear','保单年度','年度'],premium:['premium','当年保费','保费'],benefit:['benefit','annualBenefit','当年领取','当年给付','领取金额'],cashValue:['cashValue','年末现金价值','现金价值'],deathBenefit:['deathBenefit','身故保险金','身故利益']};const pick=(row,key)=>{const name=aliases[key].find(name=>Object.prototype.hasOwnProperty.call(row,name));return name===undefined?'':row[name];};const rows=(Array.isArray(input)?input:[]).map((row,index)=>{const yearValue=nullableNumber(pick(row,'year'),`第 ${index+1} 行保单年度`);if(!Number.isInteger(yearValue)||yearValue<1||yearValue>200)throw new Error(`第 ${index+1} 行保单年度必须是 1 至 200 的整数。`);return {year:yearValue,premium:nullableNumber(pick(row,'premium'),`第 ${yearValue} 年保费`),benefit:nullableNumber(pick(row,'benefit'),`第 ${yearValue} 年领取`),cashValue:nullableNumber(pick(row,'cashValue'),`第 ${yearValue} 年现金价值`),deathBenefit:nullableNumber(pick(row,'deathBenefit'),`第 ${yearValue} 年身故保险金`)};}).sort((a,b)=>a.year-b.year);for(let index=1;index<rows.length;index++)if(rows[index].year===rows[index-1].year)throw new Error(`保单年度 ${rows[index].year} 重复，请先核对原计划书。`);return rows;}
function validatePlanRows(rows){if(!Array.isArray(rows)||!rows.length)throw new Error('没有识别到有效年度数据。');if(rows[0].year!==1)throw new Error(`年度数据必须从第 1 年开始，当前从第 ${rows[0].year} 年开始。`);for(let index=0;index<rows.length;index++){const row=rows[index],expected=index+1;if(row.year!==expected)throw new Error(`年度数据不连续：缺少第 ${expected} 年，不能把第 ${row.year} 年压缩为相邻现金流。`);for(const [key,label] of [['premium','保费'],['benefit','领取'],['cashValue','现金价值'],['deathBenefit','身故保险金']])if(row[key]===null)throw new Error(`第 ${row.year} 年${label}未知，不能按 0 参与测算。请回到原计划书核对。`);}return rows;}
function parsePlanText(text){const trimmed=String(text||'').trim();if(!trimmed)throw new Error('文件内容为空。');if(trimmed.startsWith('{')||trimmed.startsWith('[')){const data=JSON.parse(trimmed);return validatePlanRows(normalizePlanRows(Array.isArray(data)?data:data.rows));}const lines=trimmed.split(/\r?\n/).filter(line=>line.trim());if(lines.length<2)throw new Error('CSV 至少需要表头和一行数据。');const headers=parseCSVLine(lines[0]);const rows=lines.slice(1).map(line=>{const cells=parseCSVLine(line),row={};headers.forEach((header,index)=>row[header]=cells[index]??'');return row;});return validatePlanRows(normalizePlanRows(rows));}
function irr(flows){if(!Array.isArray(flows)||flows.length<2||!flows.some(x=>x<0)||!flows.some(x=>x>0))return null;const npv=rate=>flows.reduce((sum,value,index)=>sum+value/((1+rate)**index),0);let low=-.9999,high=1;while(npv(high)>0&&high<1024)high*=2;if(npv(low)*npv(high)>0)return null;for(let i=0;i<180;i++){const mid=(low+high)/2;if(npv(mid)>0)low=mid;else high=mid;}const result=(low+high)/2;return Number.isFinite(result)?result:null;}
function planFlows(rows,index,terminalKey){validatePlanRows(rows);const flows=[-rows[0].premium];for(let i=1;i<=index;i++)flows[i]=rows[i-1].benefit-rows[i].premium;flows[index+1]=rows[index].benefit+rows[index][terminalKey];return flows;}
function calculatePlan(rows,c=typeof current==='function'?current():null){validatePlanRows(rows);let cumulativePremium=0,cumulativeBenefit=0,breakEvenYear=null;const calculated=rows.map((row,index)=>{cumulativePremium+=row.premium;cumulativeBenefit+=row.benefit;if(!breakEvenYear&&cumulativeBenefit+row.cashValue>=cumulativePremium)breakEvenYear=row.year;return {...row,cumulativePremium,cumulativeBenefit,surrenderIrr:irr(planFlows(rows,index,'cashValue')),deathIrr:irr(planFlows(rows,index,'deathBenefit'))};});const last=calculated.at(-1);return {currency:'CNY',timingBasis:'保费按每个保单年度期初；领取、现金价值及身故利益按该年度期末',conditionSnapshot:c?planConditionSnapshot(c):null,rows:calculated,summary:{years:calculated.length,cumulativePremium:last.cumulativePremium,cumulativeBenefit:last.cumulativeBenefit,breakEvenYear,lastSurrenderIrr:last.surrenderIrr,lastDeathIrr:last.deathIrr}};}
async function fileToBase64(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));return btoa(binary);}
function extractionReviewHTML(c){if(!planExtraction||planExtraction.customerId!==c.id)return '';if(planExtraction.status==='extracting')return `<section class="panel section-gap"><div class="panel-body"><div class="notice">正在本机识别「${escapeHTML(planExtraction.sourceName)}」的文字和表格候选行，请稍候。文件不会发送到 Dify，也不会保存原文件。</div></div></section>`;if(planExtraction.status==='error')return `<section class="panel section-gap"><div class="panel-body"><div class="notice danger">${escapeHTML(planExtraction.reason)}</div><div class="section-gap">${button('关闭识别结果','discard-extraction','small')}</div></div></section>`;const rows=planExtraction.candidates||[];return `<section class="panel section-gap"><div class="panel-head"><div><h2>识别结果复核</h2><small>${escapeHTML(planExtraction.sourceName)} · ${planExtraction.page_count} 页 · ${escapeHTML(planExtraction.mode)}</small></div>${tag(`${rows.length} 条候选`,rows.length?'blue':'orange')}</div><div class="panel-body"><div class="notice warning">这里只是识别候选，不是正式计划书数据。请对照原文件核对页码、原文和每个金额；只有勾选并确认的行会进入测算。</div>${rows.length?`<div class="table-wrap section-gap"><table class="ocr-table"><thead><tr><th>采用</th><th>来源与置信度</th><th>年度</th><th>当年保费</th><th>当年领取</th><th>现金价值</th><th>身故保险金</th></tr></thead><tbody>${rows.map((row,index)=>`<tr><td><input type="checkbox" id="extract-use-${index}" ${row.exactColumnCount&&row.confidence>=.72?'checked':''} aria-label="采用第 ${row.page} 页候选行"></td><td><strong>第 ${row.page} 页 · ${(Number(row.confidence)*100).toFixed(0)}%</strong><details><summary>查看原文</summary><p class="ocr-source">${escapeHTML(row.sourceText)}</p>${!row.exactColumnCount?'<p class="error-text">数字列数量不标准，系统只做了临时映射，请重点核对。</p>':''}</details></td>${[['year',row.year],['premium',row.premium],['benefit',row.benefit],['cashValue',row.cashValue],['deathBenefit',row.deathBenefit]].map(([field,value])=>`<td><input class="input compact-input" id="extract-${field}-${index}" inputmode="decimal" value="${escapeHTML(value)}" aria-label="第 ${row.page} 页${field}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">没有找到列结构足够清晰的年度数据。可以查看识别原文，再改用 CSV 模板导入。</div>'}<details class="section-gap"><summary>查看全部识别原文（本次页面内存）</summary><pre class="ocr-raw">${escapeHTML(planExtraction.raw_text||'')}</pre></details><div class="actions section-gap">${button('确认选中行并写入测算','apply-extracted-plan','primary',rows.length?'':'disabled')}${button('放弃本次识别','discard-extraction','small')}</div><p class="page-note">原文件和完整识别文本不会写入客户档案；确认后只保存数值、来源文件名、页数和复核记录。</p></div></section>`;}
function renderPlanner(){
 const c=current(),book=state.planBooks?.[c.id],rows=book?.rows||[],summary=book?.summary||{},currentBook=planIsCurrent(book),profileMissing=missingPlanProfile(c);
 const customerSelect=`<select id="planner-customer" aria-label="选择客户">${state.customers.map(item=>`<option value="${item.id}" ${item.id===c.id?'selected':''}>${escapeHTML(item.name)} · ${escapeHTML(item.stage)}</option>`).join('')}</select>`;
 const metrics=[['已导入年度',rows.length?`${rows.length} 年`:'未导入'],['累计保费',rows.length?moneyLabel(summary.cumulativePremium):'—'],['静态回本年度',summary.breakEvenYear?`第 ${summary.breakEvenYear} 年`:'未达到／无数据'],['末年退保口径 IRR',formatRate(summary.lastSurrenderIrr)]];
 const staleReason=book?.confirmed?(book.productVersion!==state.product.version?'产品知识版本已变化':'人物、购买需求或方案条件已变化'):'当前年度利益数据尚未人工确认';
 const status=`<div class="notice ${currentBook?'success':'warning'}">${currentBook?`已确认来源：${escapeHTML(book.sourceName)} · ${escapeHTML(book.confirmedAt)}`:`${staleReason}，这份方案不会作为可对客金额依据。`}${profileMissing.length?`<br>确认前还需补齐：${escapeHTML(profileMissing.join('、'))}。`:''}</div>`;
 const importPanel=`<div class="split"><section class="panel"><div class="panel-head"><div><h2>导入年度利益表</h2><small>CSV / JSON 直接导入；PDF / 图片在本机识别</small></div>${tag(rows.length?'已读取':'等待文件',rows.length?'blue':'')}</div><div class="panel-body"><label class="file-label">选择计划书年度利益数据<input id="plan-file" type="file" accept=".csv,.json,.txt,.pdf,.png,.jpg,.jpeg,text/csv,application/json,application/pdf,image/*"></label><div class="actions section-gap">${button('下载 CSV 模板','download-plan-template','small')}${rows.length?button(currentBook?'重新确认数据':'确认数据与原计划书一致','confirm-plan','primary small')+button('清除本方案','clear-plan','small'):''}</div><p class="page-note">PDF / 图片会在本机提取文字和候选年度行，先展示页码、原文与置信度；销售确认前不会写入金额。单个文件不超过 8 MB，PDF 最多读取前 30 页。</p></div></section><section class="panel"><div class="panel-head"><h2>${escapeHTML(c.name)}的方案字段</h2>${button('编辑字段','edit-profile','small')}</div><div class="panel-body"><dl>${[['年龄 / 性别',`${c.age} / ${c.gender}`],['保障计划',c.plan],['交费期间',c.paymentTerm],['年交／趸交保费',moneyLabel(c.premium)],['领取方式',c.receiveMode],['个人养老金账户',c.pensionAccount]].map(([label,value])=>`<div class="profile-line"><dt>${label}</dt><dd>${escapeHTML(value)}</dd></div>`).join('')}</dl><div class="notice">这些字段用于核对计划书版本，不会根据年度利益表反推客户身份或投保资格。</div></div></section></div>`;
 const cashflow=`<section class="panel section-gap"><div class="panel-head"><div><h2>逐年现金流与 IRR</h2><small>保费按期初、领取与现金价值按期末计算</small></div>${tag(currentBook?'人工已确认':'不可对客',currentBook?'green':'orange')}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>保单年度</th><th>当年保费</th><th>累计保费</th><th>当年领取</th><th>累计领取</th><th>年末现金价值</th><th>退保口径 IRR</th><th>身故利益 IRR</th></tr></thead><tbody>${rows.map(row=>`<tr><td>第 ${row.year} 年</td><td>${moneyLabel(row.premium)}</td><td>${moneyLabel(row.cumulativePremium)}</td><td>${moneyLabel(row.benefit)}</td><td>${moneyLabel(row.cumulativeBenefit)}</td><td>${moneyLabel(row.cashValue)}</td><td>${formatRate(row.surrenderIrr)}</td><td>${formatRate(row.deathIrr)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">导入正式计划书导出的年度利益表后，这里才显示金额和收益率。</div>'}<div class="panel-body"><div class="notice warning">静态回本＝累计领取＋当年现金价值不低于累计保费；IRR 是基于导入现金流的计算结果，不是保证收益、结算利率或产品统一收益率。</div></div></section>`;
 return header('方案测算','只计算计划书中已经导入并由人确认的数据，不推测任何金额。',customerSelect)+status+`<div class="metric-row section-gap">${metrics.map(([label,value])=>`<div class="panel metric"><span>${label}</span><strong>${escapeHTML(value)}</strong></div>`).join('')}</div>`+importPanel+extractionReviewHTML(c)+cashflow;
}
function extractPaymentTerms(rule,fallback='待人工录入'){const match=String(rule||'').match(/(\d+)\s*年(?:交|缴)?\s*(?:或|、|和|及|\/|，)\s*(\d+)\s*年(?:交|缴)?/);return match?`${match[1]} 年交、${match[2]} 年交`:fallback;}
function activityStatus(a,now=Date.now()){return now<new Date(a.start+'T00:00:00+08:00')?'未开始':now>=new Date(a.end+'T23:59:59.999+08:00')?'已结束':'进行中';}
function activateScheduledProduct(){const pending=state.product.pending;if(pending&&pending.effective<=today()){delete state.product.pending;applyProduct(pending);}}
function applyProduct(update){const old=state.product;state.product={...old,...update,version:old.version+1,history:[{version:old.version,rule:old.rule,facts:old.facts,effective:old.effective,scope:old.scope,sourceType:old.sourceType,source:old.source,sourceStatus:old.sourceStatus,reviewer:old.reviewer,reviewedAt:old.reviewedAt,changeReason:old.changeReason},...(old.history||[])]};delete state.product.pending;delete state.product.reviewQueue;for(const book of Object.values(state.planBooks||{}))if(book)book.confirmed=false;save();}
const sampleSegments=[{start:0,end:4,text:'准备一笔长期养老资金，先别急着选产品。'},{start:4,end:5.2,text:'停顿 1.2 秒',pause:true},{start:5.2,end:11,text:'先问自己，这笔钱近期有没有可能需要用到？'},{start:11,end:12.7,text:'停顿 1.7 秒',pause:true},{start:12.7,end:21,text:'再了解缴费安排和使用限制，具体要以核实后的资料为准。'},{start:21,end:25,text:'您最关心哪一点？可以在评论里告诉我。'}];
function renderCreation(){return header('创作中心','把“有流量”变成“有人带着真实问题来咨询”。',tag('内容拆解与文案','blue'))+`<div class="split"><section class="panel"><div class="panel-head"><h2>从一条对标内容开始</h2><span class="subtle">01 / 输入</span></div><div class="panel-body"><label class="field"><span>对标文案</span><textarea id="creation-reference">${escapeHTML(creationInput.reference)}</textarea><small>粘贴文本体验流程；此版不抓取账号或链接。</small></label><div class="equal-grid"><label class="field"><span>面向谁、处在什么情境</span><input class="input" id="creation-audience" value="${escapeHTML(creationInput.audience)}"></label><label class="field"><span>准备发到哪里</span><select id="creation-platform"><option ${creationInput.platform==='抖音'?'selected':''}>抖音</option><option ${creationInput.platform==='小红书'?'selected':''}>小红书</option></select></label></div><div class="muted-box">产品依据：${escapeHTML(state.product.name)} v${state.product.version} · ${escapeHTML(state.product.sourceStatus)}<br>目的：引发相关咨询，不承诺“爆款”或实际获客结果。</div><div class="section-gap">${button('拆解并生成文案','generate-content','primary')}</div></div></section><section class="panel"><div class="panel-head"><h2>内容结构参考</h2><span class="subtle">实战框架</span></div><div class="panel-body step-list"><div><div><strong>面向谁</strong><p class="muted">有明确需求、顾虑或生活情境的人，不只是年龄标签。</p></div></div><div><div><strong>为什么愿意听</strong><p class="muted">“这笔钱近期会不会用到”，把真实顾虑放在开头。</p></div></div><div><div><strong>产品怎样进入</strong><p class="muted">先解释问题，再用当前有效资料介绍条件与限制。</p></div></div><div><div><strong>下一步做什么</strong><p class="muted">邀请提出一个具体问题，不夸大、不强迫留资。</p></div></div><div class="notice">当前使用固定内容框架；产品事实始终从已复核的当前版本读取。</div></div></section></div><section class="panel section-gap"><div class="panel-head"><h2>文案草稿</h2>${tag(creationDraft?'等待审核':'尚未生成',creationDraft?'orange':'')}</div><div class="panel-body"><textarea id="creation-draft" aria-label="内容文案草稿" style="min-height:190px" placeholder="生成文案后可以继续编辑。">${escapeHTML(creationDraft)}</textarea><div class="row section-gap">${button('发布前检查','audit-content','primary')}${button('加入发布任务','queue-content')}${button('去视频粗剪','goto-video')}</div><div id="audit-result">${auditHTML()}</div><p class="page-note">自动检查只覆盖部分风险表达；对外发布仍需授权人员核验产品事实、完整上下文和平台规则。</p></div></section>`;}
function auditHTML(){if(!creationAudit)return '';return `<div class="notice ${creationAudit.words.length?'danger':'success'} section-gap">${creationAudit.words.length?'演示检查未通过：命中 '+creationAudit.words.map(escapeHTML).join('、')+'。请修改后重检。':'演示规则未命中风险词。仍需人工核验产品事实、上下文与该平台规则。'}</div>`;}
function renderPublishing(){const data=publishTab==='data';return header('发布与数据','先演示任务与回收口径，不调用收费发布 API。',tag('抖音 / 小红书均未连接','orange'))+`<div class="tabs"><button class="tab ${!data?'active':''}" data-action="publish-tab" data-value="tasks">发布任务</button><button class="tab ${data?'active':''}" data-action="publish-tab" data-value="data">获客效果</button></div>`+(data?`<div class="notice">以下全部是固定模拟数据，用于讨论指标设计；没有从平台采集，也不能代表实际效果。</div><div class="metric-row section-gap">${[['播放量','12,800','仅为曝光'],['有效咨询','32','提出产品 / 需求相关问题'],['已核验新增客户','8','示例人工确认'],['成交','2','示例结果，非真实业绩']].map(([a,b,c])=>`<div class="panel metric"><span>${a}</span><strong>${b}</strong><small>${c}</small></div>`).join('')}</div><div class="equal-grid"><section class="panel"><div class="panel-head"><h2>模拟获客漏斗</h2>${tag('非等比例')}</div><div class="panel-body funnel">${[['观看',12800,100],['有效咨询',32,65],['新增客户',8,38],['成交',2,18]].map(([a,n,w])=>`<div class="funnel-line"><span>${a}</span><div class="bar-track"><div class="bar-value" style="width:${w}%"></div></div><strong>${n.toLocaleString()}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>什么才算有效</h2></div><div class="panel-body"><p>“多少钱、适合谁、能不能中途使用”比单纯点赞更接近购买需求。</p><div class="notice section-gap">跨平台身份未匹配的客户标记为「来源待确认」，不能仅凭昵称判断是谁，也不能把时间上的先后当成获客归因。</div><p class="page-note">正式接入后再选择：平台授权数据、人工录入，或可追溯的渠道标记。</p></div></section></div>`:`<section class="panel"><div class="panel-head"><h2>待办清单</h2><button class="text-button" data-view="creation">＋ 从文案创建任务</button></div>${state.publish.length?state.publish.map(p=>`<div class="list-row"><div class="grow"><div class="row"><h3>${escapeHTML(p.platform)} · 内容 ${p.id.slice(-4)}</h3>${tag(p.status,p.status==='演示已发布'?'green':'orange')}</div><p class="wrap-text">${escapeHTML(p.text.slice(0,120))}${p.text.length>120?'…':''}</p><span class="subtle">产品资料 v${p.version} · ${p.version!==state.product.version?'资料已变更，需重新审核':'只通过演示规则检查'}</span></div><div class="actions">${p.status==='待人工确认'?button('人工确认并模拟发布','simulate-publish','small',`data-id="${p.id}"`)+button('取消','cancel-publish','small',`data-id="${p.id}"`):tag('无真实平台操作')}</div></div>`).join(''):'<div class="empty">还没有发布任务<br>去创作中心生成文案，检查后加入任务。</div>'}</section><div class="notice section-gap">任务不会定时或后台发布。真实账号授权、行业资质、发布接口和权限都尚未验证；不使用未授权登录或自动化脚本。</div>`);}
function renderMessages(){return header('评论与私信','让话术可编辑，让每次触达可控。',tag('固定平台样例','blue'))+`<div class="tabs">${['抖音','小红书'].map(p=>`<button class="tab ${p===messagePlatform?'active':''}" data-action="message-platform" data-value="${p}">${p}</button>`).join('')}</div><div class="equal-grid"><section class="panel"><div class="panel-head"><h2>评论回复</h2>${tag('模拟评论')}</div><div class="panel-body"><div class="row"><span class="avatar purple">林</span><div><strong>模拟用户 01</strong><p class="subtle">在视频《养老资金，先想清楚这件事》下评论</p></div></div><div class="quote-box" style="background:#f5f7fb">如果中间要用钱怎么办？</div><label class="field"><span>选择评论话术</span><select id="comment-preset"><option value="current">当前自定义话术</option><option value="question">先确认具体问题</option><option value="limit">先解释使用限制</option></select></label><label class="field"><span>要在评论下回复的内容</span><textarea id="comment-template">${escapeHTML(state.templates.comment)}</textarea></label><div class="actions">${button('保存话术','save-comment')}${button('模拟回复评论','simulate-comment','primary')}</div><hr class="divider"><div class="row">${button('评论后主动私信','unavailable','','disabled title="未验证平台账号和 API 权限"')}<span class="subtle">待验证权限与触达条件</span></div></div></section><section class="panel"><div class="panel-head"><h2>收到私信后回复</h2>${tag('模拟私信')}</div><div class="panel-body"><div class="row"><span class="avatar orange">周</span><div><strong>模拟用户 02</strong><p class="subtle">主动发起咨询 · 非真实收件箱</p></div></div><div class="quote-box" style="background:#f5f7fb">我想了解一下，给孩子买适合吗？</div><label class="field"><span>可自由编辑的私信回复</span><textarea id="dm-template">${escapeHTML(state.templates.dm)}</textarea></label><div class="actions">${button('保存话术','save-dm')}${button('模拟回复私信','simulate-dm','primary')}</div><div class="notice section-gap">发卡片、加微信归因、未添加再次触达，暂不假设平台支持。需要真实授权与频控规则确认后再接入。</div></div></section></div><section class="panel section-gap"><div class="panel-head"><h2>模拟触达记录</h2>${tag('不代表真实送达')}</div>${state.interactions.length?state.interactions.slice(0,8).map(i=>`<div class="list-row"><div class="grow"><strong>${escapeHTML(i.platform)} · ${i.type==='comment'?'评论回复':'私信回复'}</strong><p>${escapeHTML(i.text)}</p></div>${tag('仅演示','blue')}</div>`).join(''):'<div class="empty">尚无模拟回复记录</div>'}</section>`;}
function knowledgeFactsHTML(p){const f=p.facts||{},y=p.yieldModel||{};const groups=[['投保与合同',[['产品状态',p.productStatus],['备案编号',f.registrationNumber],['报备编号',f.filingNumber],['产品类型',f.category],['投保年龄',f.entryAge],['交费方式',f.payment],['每份保费',f.premiumUnit],['保险期间',f.period]]],['保障计划与责任',[['计划一',f.planOne],['计划二',f.planTwo],['祝贺金',f.congratulation],['祝福金',f.blessing],['满期保险金',f.maturity],['身故保险金',f.death]]],['客户常问与风险',[['犹豫期',f.coolingOff],['宽限期',f.gracePeriod],['现金价值 / 退保',f.cashValue],['保单贷款',f.policyLoan],['自动垫交',f.autoAdvance],['免责提示',f.exclusions],['必须用计划书计算',f.calculation]]]];const payment=`<section class="panel section-gap"><div class="panel-head"><div><h2>交费期适配矩阵</h2><small>可以检索 10 年、20 年，但不会误说成本产品可选</small></div>${tag('按产品版本隔离','blue')}</div>${(p.paymentOptions||[]).map(item=>`<div class="list-row"><div class="grow"><strong>${escapeHTML(item.term)} · ${escapeHTML(item.plans)}</strong><p>${escapeHTML(item.note)}</p></div>${tag(item.available?'本产品可选':'本产品不可选',item.available?'green':'orange')}</div>`).join('')}</section>`;const returns=`<section class="panel section-gap"><div class="panel-head"><div><h2>年度利益与 IRR</h2><small>收益必须从客户方案现金流计算，不能只抄一个比例</small></div>${tag(y.status||'待导入计划书','orange')}</div><div class="panel-body"><p>${escapeHTML(y.definition||'')}</p><div class="equal-grid section-gap"><div class="muted-box"><strong>生成前必须有</strong><p>${(y.requiredInputs||[]).map(escapeHTML).join('、')}</p></div><div class="muted-box"><strong>逐年输出字段</strong><p>${(y.metrics||[]).map(escapeHTML).join('、')}</p></div></div><div class="notice warning section-gap">${escapeHTML(y.guardrail||'')}</div></div></section>`;const sources=(p.sources||[]).map(s=>`<a class="text-button" href="${escapeHTML(s.url)}" target="_blank" rel="noreferrer">查看${escapeHTML(s.label)} ↗</a>`).join('');return `<section class="panel section-gap"><div class="panel-head"><div><h2>销售核对卡</h2><small>回答时只取与客户当前问题有关的字段，不整段照读</small></div>${tag('官方公开资料','green')}</div><div class="panel-body"><div class="triple-grid">${groups.map(([title,rows])=>`<div class="muted-box"><strong>${title}</strong><dl>${rows.filter(([,value])=>value).map(([label,value])=>`<div class="profile-line"><dt>${label}</dt><dd>${escapeHTML(value)}</dd></div>`).join('')}</dl></div>`).join('')}</div><div class="row section-gap">${sources}</div><p class="page-note">具体权利义务以保险条款、投保文件和实际保险合同为准；客户个人金额必须用正式计划书计算。</p></div></section>${payment}${returns}`;}
function renderKnowledge(){
 const p=state.product;
 const verified=isVerifiedProduct(p);
 const productView=`<div class="split"><section class="panel"><div class="panel-head"><div><h2>${escapeHTML(p.name)}</h2><small>太保官网公开产品资料 · 回答前按字段核对</small></div>${tag('当前生效 v'+p.version,verified?'green':'orange')}</div><div class="panel-body"><div class="section-label">当前有效规则</div><p class="wrap-text" style="font-size:1.15rem">${escapeHTML(p.rule)}</p><hr class="divider"><dl><div class="profile-line"><dt>生效日期</dt><dd>${escapeHTML(p.effective)}</dd></div><div class="profile-line"><dt>适用范围</dt><dd>${escapeHTML(p.scope)}</dd></div><div class="profile-line"><dt>来源类型</dt><dd>${escapeHTML(p.sourceType||'未填写')}</dd></div><div class="profile-line"><dt>资料来源</dt><dd>${escapeHTML(p.source)}</dd></div><div class="profile-line"><dt>复核状态</dt><dd>${tag(p.sourceStatus,verified?'green':'orange')}</dd></div><div class="profile-line"><dt>复核人员</dt><dd>${escapeHTML(p.reviewer||'未确认')} · ${escapeHTML(p.reviewedAt||'未记录')}</dd></div><div class="profile-line"><dt>变更原因</dt><dd>${escapeHTML(p.changeReason||'未记录')}</dd></div></dl><div class="notice ${verified?'':'warning'}">${verified?'当前工作流会读取这组已核对的官网公开资料；个人保费、保额、现金价值与领取金额仍须用正式计划书计算。':'当前版本未完成复核，Dify 不得据此生成产品事实。'}</div>${p.reviewQueue?`<div class="notice warning section-gap"><strong>有 1 条待复核更新</strong><br>${escapeHTML(p.reviewQueue.rule)}<div class="section-gap">${button('继续复核','review-pending-knowledge','small')}</div></div>`:''}${p.pending?`<div class="notice section-gap"><strong>已审核，等待生效</strong><br>${escapeHTML(p.pending.rule)}<br>生效日：${escapeHTML(p.pending.effective)}。到期前继续使用当前版本。</div>`:''}</div></section><section class="panel"><div class="panel-head"><h2>版本控制如何影响工作台</h2></div><div class="panel-body step-list"><div><div><strong>只读取当前有效且已复核版本</strong><p class="muted">待复核通知不会进入 Dify，也不会自动成为销售口径。</p></div></div><div><div><strong>旧草稿自动失效</strong><p class="muted">资料版本变化后，待发草稿和内容任务必须重新生成、重新审核。</p></div></div><div><div><strong>历史版本完整保留</strong><p class="muted">记录来源、复核人、生效日期和变更原因，便于追溯当时依据。</p></div></div></div></section></div>${knowledgeFactsHTML(p)}<section class="panel section-gap"><div class="panel-head"><h2>变更历史</h2>${tag(connection.local?'本机后端保存':'当前浏览器保存')}</div>${p.history.length?p.history.map(h=>`<div class="list-row"><div class="grow"><strong>v${h.version} · ${escapeHTML(h.changeReason||'历史版本')}</strong><p>${escapeHTML(h.rule)}</p><small>${escapeHTML(h.sourceType||'资料')}｜${escapeHTML(h.source)} · ${escapeHTML(h.reviewer||'未记录')}复核 · 原生效日期 ${escapeHTML(h.effective)}</small></div>${tag('已归档')}</div>`).join(''):'<div class="empty">还没有版本变更。点击右上角「更新资料」开始一次实战化更新。</div>'}</section>`;
 const activityView=`<div class="notice">活动按北京时间判断。结束当天 23:59:59 后自动失效，不删除历史；每次生成话术时仍会再次核对有效期。</div><div class="triple-grid section-gap">${state.activities.map(a=>{const status=activityStatus(a);return `<section class="panel content-card">${tag(status,status==='进行中'?'green':status==='已结束'?'':'blue')}<h3>${escapeHTML(a.name)}</h3><div class="activity-period">${escapeHTML(a.start)} 至 ${escapeHTML(a.end)}</div><p>${escapeHTML(a.note)}</p><div class="actions">${button('编辑 / 延期','edit-activity','small',`data-id="${a.id}"`)}${button('生成咨询草稿','activity-draft','small',`data-id="${a.id}" ${status!=='进行中'?'disabled':''}`)}</div><small>${status==='已结束'?'已从当前推广候选中排除，旧记录仍可查。':'草稿确认时仍需复核有效期与适用条件。'}</small></section>`;}).join('')}</div>`;
 return header('产品与活动','资料变了，只做三步：贴入通知 → 人工复核 → 按日期生效。',button(knowledgeTab==='products'?'＋ 更新资料':'＋ 添加活动',knowledgeTab==='products'?'update-knowledge':'new-activity','primary'))+`<div class="tabs"><button class="tab ${knowledgeTab==='products'?'active':''}" data-action="knowledge-tab" data-value="products">产品资料</button><button class="tab ${knowledgeTab==='activities'?'active':''}" data-action="knowledge-tab" data-value="activities">限时活动</button></div>`+(knowledgeTab==='products'?productView:activityView);
}
function renderReviews(){const rows=state.learning.filter(r=>reviewTab==='待确认'?r.status==='待确认':reviewTab==='已沉淀'?r.status==='已沉淀':r.outcome===reviewTab);return header('经验复盘','系统找出改过的草稿，销售确认为什么改。',tag('已确认经验进入 Dify 上下文','green'))+`<div class="metric-row">${[['待确认',state.learning.filter(r=>r.status==='待确认').length],['工作台内已记录修改',state.learning.filter(r=>r.source==='工作台内修改').length],['成功案例',state.learning.filter(r=>r.outcome==='成功').length],['失败案例',state.learning.filter(r=>r.outcome==='失败').length]].map(([s,n])=>`<div class="panel metric"><span>${s}</span><strong>${n}</strong></div>`).join('')}</div><div class="tabs">${['待确认','成功','失败','进行中','已沉淀'].map(s=>`<button class="tab ${reviewTab===s?'active':''}" data-action="review-tab" data-value="${s}">${s}</button>`).join('')}</div><div class="notice">记录的是“原草稿 → 最终确认文本”，不是键盘敲击次数。只有人工确认并标记为「已沉淀」的经验，才会按当前客户消息相关度选取最多 3 条交给 Dify；这不是模型训练，也不会覆盖产品事实。</div><div class="stack section-gap">${rows.map(r=>`<section class="panel"><div class="panel-head"><div class="row"><h2>${escapeHTML(state.customers.find(c=>c.id===r.customer)?.name||'模拟客户')} · 回复修改</h2>${tag(r.status,r.status==='已沉淀'?'green':'orange')}${tag(r.outcome)}</div><small>${escapeHTML(r.source)}</small></div><div class="panel-body"><div class="equal-grid"><div><div class="section-label">原草稿</div><div class="quote-box review-original">${escapeHTML(r.original)}</div></div><div><div class="section-label">人工确认文本</div><div class="quote-box review-revised">${escapeHTML(r.revised)}</div></div></div><p class="page-note">修改原因：${escapeHTML(r.reason)}</p><div class="actions">${button(r.status==='已沉淀'?'查看 / 修改经验':'确认修改原因','review-edit','primary small',`data-id="${r.id}"`)}${button('登记结果','review-outcome','small',`data-id="${r.id}"`)}</div></div></section>`).join('')||'<div class="panel empty">这个分类暂无记录。修改一条客户草稿并模拟发送后，会进入待确认队列。</div>'}</div>`;}
function renderSettings(){const difyStatus=connection.local&&connection.difyConfigured?tag('本地已接通','green'):connection.local?tag('后端已启动，待配置密钥','orange'):tag('未连接'),ocrStatus=connection.local?tag('本机已接通','green'):tag('仅本地版可用','orange'),asrStatus=connection.local&&connection.asrConfigured?tag('已接通','green'):connection.local?tag('待配置百炼密钥','orange'):tag('未连接');return header('连接与设置','先把流程跑顺，再把真实能力接进来。')+`<div class="equal-grid"><section class="panel"><div class="panel-head"><h2>外部连接</h2></div><div class="panel-body"><div class="notice">API 密钥只保存在本地后端，不会进入网页代码或浏览器存储。</div><div class="list-row"><div class="grow">Dify 工作流 / DeepSeek</div>${difyStatus}</div><div class="list-row"><div class="grow">客户语音 / 短视频转写<small>${escapeHTML(connection.asrModel||'qwen-audio-3.1-asr-flash')}</small></div>${asrStatus}</div><div class="list-row"><div class="grow">方案 CSV / JSON 与 IRR 计算</div>${tag('本地已接通','green')}</div><div class="list-row"><div class="grow">计划书 PDF / 图片识别</div>${ocrStatus}</div><div class="list-row"><div class="grow">已确认销售经验检索</div>${tag('已接入 Dify 上下文','green')}</div><div class="list-row"><div class="grow">模拟业务数据</div>${connection.local?tag('本机后端保存','green'):tag('仅浏览器保存','orange')}</div>${['抖音发布与消息','小红书发布与消息','企业微信客户会话','视频字级剪辑'].map(x=>`<div class="list-row"><div class="grow">${x}</div>${tag('未连接')}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>本版可以怎么试</h2></div><div class="panel-body step-list"><div><p>打开后端联调台，输入一条模拟客户消息，查看中控处理过程与Dify回复草稿。</p></div><div><p>在客户详情上传一段语音或短视频，听完或看完后选择识别结果是否可用。</p></div><div><p>在方案测算导入年度利益表或计划书截图，逐项复核后查看 IRR。</p></div><div><p>生成草稿，修改后模拟发送，再到经验复盘确认原因。</p></div><div class="notice warning">当前只输入已获授权的测试材料。本机后端已持久化业务记录，但原媒体不会保存在工作台数据库。</div><div class="section-gap"><a class="btn primary" href="/backend-test.html" target="_blank" rel="noopener">打开后端联调台</a> ${button('重置演示数据','reset-demo','danger')}</div></div></section></div><p class="page-note">工作台是销售辅助原型，不是承保、出单或自动触达系统。所有 AI 结果必须人工确认。</p>`;}
function startKnowledgeUpdate(existing=state.product.reviewQueue){openModal('更新产品资料','粘贴业务通知或读取 TXT；先比对，再由人决定是否进入有效知识库。',`<label class="field"><span>新规则 / 通知原文</span><textarea id="update-text" placeholder="例如：缴费期间调整为 5 年或 10 年，适用于指定日期后的新投保咨询。">${escapeHTML(existing?.rule||'')}</textarea></label><div class="row">${button('填入训练更新','fill-update','small')}<label class="text-button">或读取本地 TXT<input type="file" id="knowledge-file" accept=".txt,text/plain" style="display:block;max-width:230px;font-size:12px"></label></div><p class="page-note">当前版本原样保留通知文本并记录版本元数据；PDF / 图片解析尚未接入。</p>`,button('查看变化','preview-update','primary'));}
function startActivity(a){editingActivity=a?.id||null;openModal(a?'编辑活动':'添加活动','北京时间；到期自动失效，历史记录保留。',`<label class="field"><span>活动名称</span><input id="activity-name" class="input" value="${escapeHTML(a?.name||'')}"></label><div class="equal-grid"><label class="field"><span>开始日期</span><input id="activity-start" class="input" type="date" value="${a?.start||today()}"></label><label class="field"><span>结束日期</span><input id="activity-end" class="input" type="date" value="${a?.end||today()}"></label></div><label class="field"><span>说明 / 适用条件</span><textarea id="activity-note">${escapeHTML(a?.note||'请写明参与对象、服务内容、限制条件及不适用情形。')}</textarea></label>`,button('保存活动','save-activity','primary'));}
function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function extractDocumentFile(file,c){
 if(!connection.local){planExtraction={status:'error',customerId:c.id,sourceName:file.name,reason:'PDF / 图片识别依赖 Mac 本机后端；公开网页只能使用 CSV / JSON 导入。'};render();return toast('请在 http://127.0.0.1:8788 使用本机识别。');}
 if(file.size>8000000){planExtraction={status:'error',customerId:c.id,sourceName:file.name,reason:'文件超过 8 MB，请压缩或拆分后重试。'};render();return;}
 planExtraction={status:'extracting',customerId:c.id,sourceName:file.name};render();
 try{
  const response=await fetch('/api/plan-extract',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({filename:file.name,mime_type:file.type||'',data_base64:await fileToBase64(file)})});
  const result=await response.json();
  if(!response.ok)throw new Error(result.reason||'计划书识别失败。');
  planExtraction={...result,status:'review',customerId:c.id,sourceName:file.name};render();toast(`已找到 ${result.candidates?.length||0} 条候选年度数据，请逐项核对。`);
 }catch(error){planExtraction={status:'error',customerId:c.id,sourceName:file.name,reason:error.message||'计划书识别失败。'};render();toast('计划书识别失败，请查看页面提示。');}
}
